// Managed plugin kit fixture. All paths and credentials are generated by the kit.
import { readFile, writeFile } from 'node:fs/promises';
import { appendFileSync } from 'node:fs';
import { join } from 'node:path';
import { definePlugin, localEnvironment, serve, tool } from '@modular-agent/core';
const {scopes,auditFile,...listener} = JSON.parse(await readFile(process.env.MA_PLUGIN_FIXTURE,'utf8'));
try {
  const server = await serve(({callerId}) => {
    const audit = event => appendFileSync(auditFile,JSON.stringify({event,callerId})+'\n');
    audit('factory');
    const {project,stateDir} = scopes.find(scope=>scope.callerId===callerId);
    const marker = join(stateDir,'marker');
    return definePlugin({name:'caller-fixture',setup(r) {
      audit('setup'); r.environment(localEnvironment(project));
      r.tool(tool({name:'bash',description:'Run on the calling host',input:{type:'object',properties:{command:{type:'string'}},required:['command']},
        async run({command},cx) { return (await cx.environment.exec(command)).output; }}));
      r.tool(tool({name:'caller_probe',description:'Read the authenticated caller’s marker',input:{type:'object',properties:{callerId:{type:'string'},write:{type:'string'}}},
        async run({write}) {
          const previous=await readFile(marker,'utf8').catch(e=>{if(e.code==='ENOENT') return null; throw e;});
          if (write!==undefined) await writeFile(marker,write,{mode:0o600});
          return {content:[],value:{callerId,previous}};
        }}));
    }});
  },listener);
  console.log(JSON.stringify({url:server.url}));
  process.once('SIGTERM',()=>void server.close());
} catch (e) {
  if (e.code!=='invalid_composition') throw e;
  console.log(JSON.stringify({error:e.code})); process.exitCode=1;
}
